(function(root){
'use strict';
const levels=['easy','medium','hard','expert'],labels={easy:'Łatwy',medium:'Średni',hard:'Trudny',expert:'Ekspert'};
function dailyId(ids,date=new Date().toISOString().slice(0,10)){if(!ids.length)return null;let hash=2166136261;for(const c of 'sudoku-exchange-v1:'+date)hash=Math.imul(hash^c.charCodeAt(0),16777619)>>>0;return ids[hash%ids.length];}
function chooseId(ids,completed,random=Math.random,exclude){const fresh=ids.filter(id=>!completed.has(id)&&id!==exclude),pool=fresh.length?fresh:ids.filter(id=>id!==exclude);return pool.length?pool[Math.min(pool.length-1,Math.floor(Math.max(0,random())*pool.length))]:ids[0]||null;}
function matchesGivens(givens,values){return /^[0-9]{81}$/.test(givens)&&values.length===81&&[...givens].every((d,i)=>d==='0'||Number(d)===values[i]);}
const api={dailyId,chooseId,matchesGivens,levels};root.SudokuLibrary=api;if(typeof module!=='undefined')module.exports=api;
if(typeof document==='undefined')return;
const $=id=>document.getElementById(id),dialog=$('library-dialog'),levelSelect=$('library-level'),status=$('library-status'),start=$('library-start'),daily=$('library-daily');
const levelInputs=levels.map(level=>$('library-level-'+level));
for(const input of levelInputs)input.onchange=()=>{if(input.checked){levelSelect.value=input.value;countLabel();}};
const completed=new Set(),recent=new Map(),cache=new Map();let manifestPromise,manifest=null,epoch=0,current=null;
try{const saved=JSON.parse(localStorage.getItem('sudoku-library-v1')||'{}');for(const id of saved.completed||[])if(/^[a-f0-9]{16}$/.test(id))completed.add(id);for(const record of saved.recent||[])if(/^[a-f0-9]{16}$/.test(record.id)&&/^[0-9]{81}$/.test(record.givens)&&levels.includes(record.level)&&Number.isFinite(record.rating))recent.set(record.givens,record);}catch{}
function persist(){try{localStorage.setItem('sudoku-library-v1',JSON.stringify({completed:[...completed],recent:[...recent.values()].slice(-1000)}));}catch{status.textContent='Postęp nie może być zapisany na tym urządzeniu. Nadal możesz grać.';}}
function countLabel(){if(!manifest)return;const count=manifest.levels[levelSelect.value].chunks.flatMap(c=>c.ids).filter(id=>completed.has(id)).length;$('library-progress').textContent=`Ukończone na tym urządzeniu: ${count} / ${manifest.levels[levelSelect.value].count}`;}
async function json(file){const response=await fetch(new URL('puzzles/'+file,document.baseURI));if(!response.ok)throw Error('library-fetch');return response.json();}
function getManifest(){if(!manifestPromise)manifestPromise=json('manifest.json').then(data=>{if(data.format!==1||!levels.every(l=>data.levels?.[l]?.chunks?.length))throw Error('manifest');manifest=data;return data;}).catch(error=>{manifestPromise=null;throw error;});return manifestPromise;}
function getChunk(file){if(!/^(easy|medium|hard|expert)-\d+\.json$/.test(file))return Promise.reject(Error('chunk'));if(!cache.has(file))cache.set(file,json(file).catch(e=>{cache.delete(file);throw e;}));return cache.get(file);}
function setBusy(busy){start.disabled=busy;daily.disabled=busy;levelSelect.disabled=busy;for(const input of levelInputs)input.disabled=busy;}
api.onRender=(givens,solved,values)=>{const active=values.some(Boolean);$('play-launch').classList.toggle('compact',active);current=recent.get(givens)||null;const info=$('library-current');info.hidden=!current;if(current)info.textContent=`Poziom: ${labels[current.level]} · Sudoku #${current.id} · Ocena SE: ${current.rating.toFixed(1)}`;if(current&&solved&&matchesGivens(current.givens,values)&&!completed.has(current.id)){completed.add(current.id);persist();countLabel();}};
$('open-library').onclick=async()=>{const request=++epoch;dialog.showModal();setBusy(true);status.textContent='Wczytywanie biblioteki…';try{await getManifest();if(request!==epoch||!dialog.open)return;countLabel();status.textContent='';}catch{if(request===epoch&&dialog.open)status.textContent='Nie udało się wczytać biblioteki. Sprawdź internet i spróbuj ponownie.';}finally{if(request===epoch)setBusy(false);}};
dialog.addEventListener('close',()=>{epoch++;setBusy(false);});levelSelect.onchange=countLabel;
async function loadPuzzle(isDaily){const request=++epoch;setBusy(true);status.textContent='Wczytywanie planszy…';try{const data=await getManifest(),level=levelSelect.value,entries=data.levels[level].chunks,ids=entries.flatMap(c=>c.ids),id=isDaily?dailyId(ids):chooseId(ids,completed,Math.random,current?.id),chunk=entries.find(c=>c.ids.includes(id)),records=await getChunk(chunk.file),record=records.find(p=>p.id===id);if(!record||!/^[0-9]{81}$/.test(record.givens)||!Number.isFinite(record.rating))throw Error('puzzle');if(request!==epoch||!dialog.open)return;
 const board=Sudoku.validate({values:[...record.givens].map(Number)});if($('library-notes').checked)board.notes=board.values.map((_,i)=>Sudoku.candidates(board.values,i));recent.delete(record.givens);recent.set(record.givens,{id:record.id,givens:record.givens,level,rating:record.rating});while(recent.size>1000)recent.delete(recent.keys().next().value);persist();dialog.close();replace(board,isDaily?'Wczytano dzisiejszą łamigłówkę. Miłego rozwiązywania!':'Wczytano sudoku z biblioteki. Miłego rozwiązywania!');
 }catch{if(request===epoch&&dialog.open)status.textContent='Nie udało się wczytać planszy. Spróbuj ponownie; obecne sudoku pozostaje bez zmian.';}finally{if(request===epoch)setBusy(false);}}
start.onclick=()=>loadPuzzle(false);daily.onclick=()=>loadPuzzle(true);
api.onRender(initial.values.join(''),state.values.every(Boolean)&&!Sudoku.conflicts(state.values).some(Boolean),state.values);
})(globalThis);
